// Generated by sova from trails/settings-save/trail.yaml
// Do not edit. Change the trail, then run `sova emit`.
import { expect, test } from '@playwright/test';

test('Changing the display name updates the dashboard greeting', async ({ page }) => {
  await test.step('Open the app and sign in', async () => {
    await page.goto('/');
    await page.getByRole('textbox', { name: 'Email', exact: true }).fill('ada@example.com');
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill('correct-horse');
    await page.getByRole('button', { name: 'Sign in', exact: true }).click();
  });

  await test.step('Open Settings', async () => {
    await page.getByRole('link', { name: 'Settings', exact: true }).click();
  });

  await test.step('Change the display name to Grace and pick the dark theme', async () => {
    await page.getByRole('textbox', { name: 'Display name', exact: true }).fill('Grace');
    await page.getByRole('combobox', { name: 'Theme', exact: true }).selectOption('dark');
  });

  await test.step('Save', async () => {
    await page.getByRole('button', { name: 'Save', exact: true }).click();
  });

  await test.step('The save is confirmed', async () => {
    await expect(page.getByRole('status', { name: 'Settings saved', exact: true }).or(page.getByRole('status').filter({ hasText: /^Settings saved$/ }))).toBeVisible();
    await expect(page.getByRole('combobox', { name: 'Theme', exact: true })).toHaveValue('dark');
  });

  await test.step('Go back to the dashboard', async () => {
    await page.getByRole('link', { name: 'Dashboard', exact: true }).click();
  });

  await test.step('The greeting uses the new name', async () => {
    await expect(page.getByRole('paragraph').filter({ hasText: /^Signed in as Grace$/ })).toBeVisible();
  });
});
